
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_m11_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_m11", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.558576654059264e+00, -1.577220222808608e+00, -1.590784731424932e+00, -1.585190862820850e+00, -1.534653932693949e+00, -1.409469133410856e+00, -1.228755725912965e+00, -1.146129108326269e+00, -1.223018626302799e+00, -1.116418920192601e+00, -7.032490055991588e-01, -3.650417387147180e-01, -2.472904731466973e-01, -1.896318819190640e-01, -1.591794316901852e-01, -8.286810784310894e-02, -2.355708370908556e-02, -1.836085725236141e-03, -2.064846317021532e-05, -2.841138321552680e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


